mapper.select:
SELECT BIZ_CD, BIZ_NM, BIZ_DESC, USE_YN, REG_AT, REG_BY, UPD_AT, UPD_BY
  FROM TB_CO_TERMS_BIZ
 WHERE BIZ_CD = #{bizCd}

SELECT TERMS_CD, TERMS_VER, TERMS_NM, TERMS_CN, PDF_URL, CN_HASH, EFFECT_DT, USE_YN, REG_AT, REG_BY
  FROM TB_CO_TERMS
 WHERE TERMS_CD = #{termsCd} AND TERMS_VER = #{termsVer}

SELECT a.AGREE_NO, a.BIZ_CD, b.BIZ_NM, a.CUST_ID, a.CHANNEL, a.CLIENT_IP, a.AGREE_AT,
       (SELECT COUNT(*) FROM TB_CO_TERMS_AGREE_DTL d WHERE d.AGREE_NO = a.AGREE_NO AND d.AGREE_YN = 'Y') AS AGREE_CNT,
       (SELECT COUNT(*) FROM TB_CO_TERMS_AGREE_DTL d WHERE d.AGREE_NO = a.AGREE_NO) AS TOTAL_CNT
  FROM TB_CO_TERMS_AGREE a
  LEFT JOIN TB_CO_TERMS_BIZ b ON b.BIZ_CD = a.BIZ_CD

    AND a.BIZ_CD = #{bizCd}
    AND a.CUST_ID = #{custId}

 ORDER BY a.AGREE_NO DESC
 LIMIT #{limit}
